<script setup>
import {ref,computed,watch} from 'vue'
import client from '../api/client'
const props=defineProps({crop:String})
const graph=ref(null),selected=ref(''),filter=ref(''),question=ref(''),answer=ref(null),error=ref(''),busy=ref(false)
const params=new URLSearchParams(location.search)
question.value=(params.get('question')||'').slice(0,500)
let generation=0
const nodes=computed(()=>(graph.value?.nodes||[]).filter(n=>String(n.name||n.id).includes(filter.value.trim())))
const nodeMap=computed(()=>Object.fromEntries((graph.value?.nodes||[]).map(n=>[n.id,n.name||n.id])))
const edges=computed(()=>(graph.value?.edges||[]).filter(e=>e.source===selected.value||e.target===selected.value).slice(0,30))
const cropName=computed(()=>({pear:'泊头鸭梨',wheat:'黄骅旱碱麦',jujube:'沧州金丝小枣',vegetable:'青县设施蔬菜'}[props.crop]))
const neighbors=computed(()=>[...new Set(edges.value.map(e=>e.source===selected.value?e.target:e.source))].filter(id=>id!==selected.value).slice(0,10).map((id,i,all)=>{
 const angle=i*Math.PI*2/all.length-Math.PI/2
 return {id,name:nodeMap.value[id]||id,x:300+Math.cos(angle)*205,y:235+Math.sin(angle)*165}
}))
const answerText=computed(()=>{
 const value=answer.value?.user_answer||answer.value?.answer||answer.value?.graphrag?.answer||answer.value?.message
 return typeof value==='string'?value:value?JSON.stringify(value,null,2):''
})
async function load(){
 const current=++generation;graph.value=null;answer.value=null;selected.value='';error.value=''
 try{const data=(await client.get('/api/graph',{params:{crop:props.crop}})).data;if(current===generation){graph.value=data;selected.value=data.nodes?.some(n=>n.id===params.get('entity'))?params.get('entity'):data.edges?.[0]?.source||data.nodes?.[0]?.id||''}}
 catch(e){if(current===generation)error.value=requestError(e,'图谱服务暂不可用，请检查 AI 服务与图谱数据库后重试。')}
}
function requestError(e,fallback){
 if(e.response?.status===401)return '登录已失效，请返回平台重新登录后加载图谱。'
 const detail=e.response?.data?.error||e.response?.data?.message
 return typeof detail==='string'?detail:fallback
}
async function ask(){
 if(busy.value||!question.value.trim())return
 const current=generation,crop=props.crop;busy.value=true;error.value='';answer.value=null
 const path={pear:'graphrag',wheat:'wheat',jujube:'jujube',vegetable:'qingxian'}[crop]
 try{const data=(await client.post('/api/'+path+'/ask',{question:question.value.trim()})).data;if(current===generation)answer.value=data}
 catch(e){if(current===generation)error.value=requestError(e,'知识研判依赖不可用，请检查模型、索引与图谱。')}
 finally{busy.value=false}
}
watch(()=>props.crop,load,{immediate:true})
</script>
<template>
<main class="knowledge">
<section class="hero"><div><div class="eyebrow">农业知识 / {{cropName}}</div><h1>多作物知识工作台</h1><p>从症状找到关联，让每一条建议有据可循。</p></div><button class="refresh" @click="load">↻ 刷新图谱</button></section>
<div class="graph-summary"><span class="status-dot"></span><span>{{graph?'图谱已连接':'正在连接图谱'}}</span><span class="summary-divider"></span><strong>{{graph?.nodes?.length||0}}</strong><span>知识实体</span><strong>{{graph?.edges?.length||0}}</strong><span>关联关系</span><span class="summary-caption">{{cropName}} · 独立作物知识库</span></div>
<p v-if="crop==='vegetable'" class="note">青县设施蔬菜当前支持知识查询。番茄视觉仍处于数据准备阶段，尚无已上线模型。</p>
<p v-if="error" role="alert" class="error">{{error}}</p>
<div class="knowledge-grid">
<section class="card entity-panel"><div class="panel-heading"><h2>知识实体</h2><span>{{nodes.length}}</span></div><p class="muted">检索并选择需要探索的知识</p><div class="search-field"><span>⌕</span><input v-model="filter" aria-label="搜索图谱实体" placeholder="搜索症状、风险、措施"></div><div class="entity-list"><button v-for="node in nodes" :key="node.id" :aria-pressed="selected===node.id" @click="selected=node.id"><span class="entity-mark">{{String(node.name||node.id).slice(0,1)}}</span><span class="entity-copy"><strong>{{node.name||node.id}}</strong><small>{{node.type}}</small></span><span class="entity-arrow">›</span></button></div><p v-if="graph&&!nodes.length" class="muted">没有匹配实体，试试其他关键词。</p></section>
<section class="card relation-panel"><div class="panel-heading"><h2>关联关系</h2><span>点击节点探索</span></div><div class="graph-canvas"><svg v-if="selected" viewBox="0 0 600 470" role="img" aria-label="当前实体与直接关联实体的知识图谱"><line v-for="node in neighbors" :key="'line-'+node.id" x1="300" y1="235" :x2="node.x" :y2="node.y"/><g v-for="node in neighbors" :key="node.id" class="graph-node" role="button" tabindex="0" :aria-label="'探索 '+node.name" @click="selected=node.id" @keydown.enter.prevent="selected=node.id" @keydown.space.prevent="selected=node.id"><circle :cx="node.x" :cy="node.y" r="26"/><text :x="node.x" :y="node.y+5">{{String(node.name).slice(0,1)}}</text><text class="node-label" :x="node.x" :y="node.y+45">{{String(node.name).slice(0,12)}}</text><title>{{node.name}}</title></g><circle class="center-halo" cx="300" cy="235" r="53"/><circle class="center-node" cx="300" cy="235" r="38"/><text class="center-letter" x="300" y="242">{{String(nodeMap[selected]||'').slice(0,1)}}</text><text class="center-label" x="300" y="302">{{String(nodeMap[selected]||'').slice(0,16)}}</text></svg><div v-else class="graph-empty">选择左侧实体，探索知识关联</div><span class="canvas-legend"><i></i> 当前实体 <i></i> 直接关联</span></div><div class="relations-heading"><strong>{{nodeMap[selected]||'关联详情'}}</strong><span>{{edges.length}} 条直接关系</span></div><div class="relation-list"><article v-for="edge in edges" :key="edge.id"><div class="relationship"><strong>{{nodeMap[edge.source]}}</strong><span>{{edge.relation}}</span><strong>{{nodeMap[edge.target]}}</strong></div><p v-if="edge.scope||edge.evidence_level||edge.review_status" class="muted">{{edge.scope||edge.evidence_level||edge.review_status}}</p></article><p v-if="selected&&!edges.length" class="muted">该实体暂无直接关系，可以选择其他实体继续探索。</p></div><p class="boundary">图中最多显示 10 个邻接实体；关系详情最多 30 条。知识关联不代表疾病确诊。</p></section>
<section class="card question-panel"><div class="panel-heading"><h2>循证问答</h2><span class="evidence-tag">知识检索</span></div><p class="question-intro">描述你观察到的情况，查询作物资料与相关证据。</p><div class="question-context"><span>当前知识库</span><strong>{{cropName}}</strong></div><label class="question-label" for="crop-question">你的问题</label><textarea id="crop-question" v-model="question" maxlength="500" rows="6" aria-label="作物知识问题" :placeholder="`描述${cropName}的症状、环境或管理问题…`"></textarea><div class="question-count">{{question.length}} / 500</div><button class="primary" :disabled="busy||!question.trim()" @click="ask">{{busy?'检索与核查中…':'查询知识与证据'}} <span v-if="!busy">↗</span></button><div v-if="!answerText" class="answer-guide"><span class="guide-symbol">✧</span><strong>从一个具体问题开始</strong><p>补充作物、症状与环境，帮助检索更贴近现场的资料。</p></div><p v-if="answer?.status==='evidence_only'" class="note">轻量知识检索 · 展示资料原文与图谱关联，未生成诊断结论。</p><pre v-if="answerText" class="answer">{{answerText}}</pre><details v-if="answer"><summary>查看证据与核查详情</summary><pre>{{JSON.stringify(answer,null,2)}}</pre></details><p class="boundary">缺少本地证据时保留不确定性。</p></section>
</div></main>
</template>
<style scoped>
.knowledge{--forest:#276653;--ink:#243f36;--muted:#82938b;max-width:1720px;padding:24px 30px 32px;color:var(--ink)}.hero{margin-bottom:20px}.hero h1{font-size:28px;letter-spacing:-.6px;margin:7px 0 8px;font-weight:650}.hero p{font-size:13px}.eyebrow{font-size:11px;color:#668478;letter-spacing:1px}.refresh{padding:9px 14px;border:1px solid #d5e2da;border-radius:10px;background:white;color:var(--forest);white-space:nowrap}.graph-summary{display:flex;align-items:center;gap:9px;font-size:12px;color:#758a7f;padding:13px 17px;background:#e8efea;border:1px solid #dce7df;border-radius:12px;margin-bottom:20px}.graph-summary strong{font-family:Consolas,monospace;font-size:17px;color:var(--forest);margin-left:12px}.summary-divider{height:16px;width:1px;background:#c8d8ce;margin:0 9px}.summary-caption{margin-left:auto}.status-dot{width:7px;height:7px;background:#448268;border-radius:50%}.knowledge-grid{display:grid;grid-template-columns:250px minmax(0,1fr) 320px;gap:16px;align-items:start}.knowledge-grid>.card{min-width:0;padding:20px;background:#fff;border:1px solid #dfe7e2;border-radius:16px;box-shadow:0 6px 24px #233f3705;animation:panel-enter .4s ease both}.relation-panel{animation-delay:.05s!important}.question-panel{animation-delay:.1s!important}.panel-heading{display:flex;justify-content:space-between;align-items:center;gap:8px}.panel-heading h2{font-size:15px;margin:0;font-weight:650}.panel-heading>span{font-size:11px;color:#82938b}.muted{color:var(--muted);font-size:11px}.search-field{display:flex;align-items:center;gap:8px;border:1px solid #dfe7e2;background:#f7faf8;border-radius:10px;padding:0 11px;margin:16px 0;color:#708a7b}.search-field input{width:100%;min-width:0;border:0;background:transparent;padding:11px 0;font-size:12px;outline-offset:0}.entity-list{height:590px;overflow:auto;display:flex;flex-direction:column;gap:5px;scrollbar-width:thin;scrollbar-color:#ccdad1 transparent}.entity-list button{display:flex;align-items:center;gap:10px;flex-shrink:0;text-align:left;padding:11px 9px;border:1px solid transparent;border-radius:10px;background:transparent;color:var(--ink);transition:background .18s,border-color .18s}.entity-list button:hover{background:#f2f7f4}.entity-list button[aria-pressed=true]{background:#eaf3ed;border-color:#cce0d3}.entity-mark{display:grid;place-items:center;flex:0 0 31px;height:31px;border-radius:9px;background:#eef3ef;color:#60836f;font-size:13px}.entity-list button[aria-pressed=true] .entity-mark{background:var(--forest);color:white}.entity-copy{min-width:0;flex:1}.entity-copy strong{display:block;font-size:12px;font-weight:550;overflow-wrap:anywhere}.entity-copy small{display:block;font-size:10px;color:#8c9c92;margin-top:2px}.entity-arrow{color:#a3b4a9}.graph-canvas{position:relative;margin:18px -4px 14px;border:1px solid #e6eee8;border-radius:13px;background-color:#f7faf8;background-image:radial-gradient(#ccdcd2 1px,transparent 1px);background-size:18px 18px;overflow:hidden}.graph-canvas svg{display:block;width:100%;min-height:300px}.graph-canvas line{stroke:#b7cec0;stroke-width:1.5}.graph-node{cursor:pointer;outline:none}.graph-node circle{fill:#fff;stroke:#99bba6;stroke-width:1.5;transition:fill .2s,stroke .2s}.graph-node:hover circle,.graph-node:focus circle{fill:#dceee2;stroke:#276653;stroke-width:3}.graph-node text{text-anchor:middle;fill:#44715b;font-size:15px;pointer-events:none}.graph-node .node-label{font-size:11px;fill:#657d6f}.center-halo{fill:#2766530d;stroke:#27665315}.center-node{fill:var(--forest);stroke:white;stroke-width:4}.center-letter{text-anchor:middle;fill:white;font-size:23px}.center-label{text-anchor:middle;fill:var(--forest);font-size:13px;font-weight:600}.canvas-legend{position:absolute;bottom:12px;left:14px;display:flex;align-items:center;gap:7px;font-size:10px;color:#83978b;background:#f7faf8dc;padding:3px 7px;border-radius:6px}.canvas-legend i{width:6px;height:6px;background:var(--forest);border-radius:50%}.canvas-legend i:nth-of-type(2){margin-left:8px;background:white;border:1px solid #8cab99}.graph-empty{height:350px;display:grid;place-items:center;color:var(--muted);font-size:12px}.relations-heading{display:flex;align-items:center;justify-content:space-between;gap:12px;font-size:12px;margin:18px 0 10px}.relations-heading span{font-size:10px;color:var(--muted);white-space:nowrap}.relation-list{max-height:180px;overflow:auto;scrollbar-width:thin}.relation-list article{padding:10px 0;border-bottom:1px solid #eef2ef}.relationship{display:flex;align-items:center;gap:8px;flex-wrap:wrap;font-size:11px}.relationship strong{font-weight:500}.relationship span{padding:2px 7px;border-radius:5px;background:#edf4ef;color:#5e816d;font-size:10px}.relationship span:before{content:'→ ';}.relationship span:after{content:' →';}.boundary{font-size:10px;line-height:1.7;color:#94a298;margin:16px 0 0}.evidence-tag{background:#ecf4ef;color:#5b846e!important;border-radius:5px;padding:3px 7px}.question-intro{font-size:12px;color:#82938b;line-height:1.8;margin:14px 0 18px}.question-context{display:flex;justify-content:space-between;align-items:center;font-size:11px;padding:12px;background:#f3f7f4;border-radius:9px;color:#82938b}.question-context strong{color:#4d725e;font-weight:500}.question-label{font-size:12px;margin:22px 0 8px;color:#567361}textarea{width:100%;min-height:155px;resize:vertical;border:1px solid #d7e3db;border-radius:10px;background:#fcfdfc;padding:12px;color:var(--ink);font:inherit;font-size:12px;line-height:1.8;transition:border .2s}textarea:focus{outline:2px solid #27665320;border-color:#6c9d7c}textarea::placeholder{color:#a0aea4}.question-count{text-align:right;font-family:Consolas,monospace;font-size:10px;color:#99a79e;margin-top:5px}.primary{display:flex;align-items:center;justify-content:space-between;margin-top:12px;background:var(--forest);border-radius:10px;font-size:12px}.primary span{font-size:17px}.answer-guide{text-align:center;padding:30px 15px 22px;margin-top:20px;border-top:1px solid #edf2ef;color:#869c8d}.guide-symbol{display:block;font-size:27px;color:#6f9780;margin-bottom:9px}.answer-guide strong{font-size:12px;font-weight:500;color:#637f6c}.answer-guide p{font-size:11px;line-height:1.8;margin:8px 0}.answer,pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:500px;overflow:auto;font:inherit;font-size:12px;line-height:1.9}.answer{padding:14px;background:#f3f8f4;border-radius:10px;margin-top:20px}@keyframes panel-enter{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:none}}@media(min-width:1500px){.knowledge-grid{grid-template-columns:280px minmax(0,1fr) 350px}}@media(max-width:1100px){.knowledge-grid{grid-template-columns:230px minmax(0,1fr)}.question-panel{grid-column:1/-1}.entity-list{height:560px}.summary-caption{display:none}}@media(max-width:650px){.knowledge{padding:20px 14px}.hero h1{font-size:23px}.hero{gap:12px}.hero p{font-size:11px}.refresh{font-size:11px;padding:8px}.knowledge-grid{grid-template-columns:1fr}.question-panel{grid-column:auto}.entity-list{height:240px}.graph-summary{gap:6px;padding:10px;font-size:10px;flex-wrap:wrap}.graph-summary strong{margin-left:5px}.summary-divider{margin:0 3px}.graph-canvas svg{min-height:0}.hero .eyebrow{font-size:10px}}@media(prefers-reduced-motion:reduce){.knowledge-grid>.card{animation:none}.entity-list button,.graph-node circle,textarea{transition:none}}
</style>
